    return null;
  };

  const guardContent = renderGuardContent();
  if (guardContent) {
    return (
      <div className="wireframe-layout">
        {renderHeader()}
        <div className="wireframe-body" style={{ justifyContent: 'center' }}>
          {guardContent}
