                  <span className="wf-tag">Subject Detail</span>
                  <h2>{viewingSubject.name}</h2>
                  <p className="wf-subtitle">Modules and your personal study pad.</p>
                </div>
                <button className="wf-btn-outline" onClick={() => setViewingSubject(null)}>
