                    {videos.filter(v => 
                      v.subject_name === viewingSubject.name || 
                      v.subject_id === viewingSubject._id
                    ).length > 0 ? (
                      videos.filter(v => 
                        v.subject_name === viewingSubject.name || 
                        v.subject_id === viewingSubject._id
