                  const subjectName = video.subject?.name || 'Module';

                  return (
                    <div key={videoId} className="wf-course-card" style={{ position: 'relative' }}>
                      <div className="wf-course-icon" style={{ 
                        height: '160px', 
                        background: isLocked ? '#f3f4f6' : '#111827',
