                          top: '10px', 
                          right: '10px', 
                          background: 'rgba(255,255,255,0.9)', 
                          color: '#111827',
                          padding: '4px 8px',
                          borderRadius: '4px',
                          fontSize: '0.7rem',
                          fontWeight: 'bold'
                        }}>
                          {subjectName}
                        </span>
                        {quizzes.some(q => String(q.after_video_id) === String(videoId)) && (
                          <div style={{ 
                            position: 'absolute', 
                            top: '10px', 
                            left: '10px', 
                            background: '#f59e0b', 
                            color: 'white',
                            padding: '4px 8px',
                            borderRadius: '4px',
                            fontSize: '0.7rem',
                            fontWeight: 'bold',
                            display: 'flex',
                            alignItems: 'center',
                            gap: '5px'
                          }}>
                            <FaClipboardList /> QUIZ
                          </div>
