                <div style={{ textAlign: 'center', padding: '60px', background: '#f9fafb', borderRadius: '15px' }}>
                   <p style={{ color: '#6b7280' }}>No modules available for this subject yet.</p>
                </div>
              )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default StudentDashboard;
